func dtFillRandom(c *port.Cells, n int32, seed int64) int32 {
	// n splitmix bytes: incompressible.
	var st *port.Cells = port.NewCells()
	var i int32 = 0
	splitmix.SmSeed(st, seed)
	port.CellsDrop(c, 0)
	for i < n {
		port.CellsPush(c, splitmix.SmBelow(st, 256))
		i += 1
	}
	return n
}

func dtLetter(word int32, k int32) int32 {
	return 97 + ((splitmix.SmLo(splitmix.SmAt(777, (word*16)+k)) & 2147483647) % 26)
}

func dtFillText(c *port.Cells, n int32, seed int64) int32 {
	// n bytes of pseudo-text: words from a vocabulary of 48, 2..9 letters,
	// a space after each and a newline after about every twelfth.
	var st *port.Cells = port.NewCells()
	var w int32 = 0
	var k int32 = 0
	var cnt int32 = 0
	splitmix.SmSeed(st, seed)
	port.CellsDrop(c, 0)
	for port.CellsLen(c) < n {
		w = splitmix.SmBelow(st, 48)
		k = 0
		for k < (2 + (w % 8)) {
			port.CellsPush(c, dtLetter(w, k))
			k += 1
		}
		cnt += 1
		if (cnt % 12) == 0 {
			port.CellsPush(c, 10)
		} else {
			port.CellsPush(c, 32)
		}
	}
	port.CellsDrop(c, n)
	return n
}

func dtFillRepeat(c *port.Cells, n int32, a int32, b int32, d int32) int32 {
	// n bytes of a, b, d repeated.
	var i int32 = 0
	port.CellsDrop(c, 0)
	for i < n {
		port.CellsPush(c, a)
		port.CellsPush(c, b)
		port.CellsPush(c, d)
		i += 3
	}
	port.CellsDrop(c, n)
	return n
}

func dtCompress(ws *port.Cells, z *port.Buf, src *port.Cells, n int32, mode int32) int32 {
	// src[0, n) in one write, in block mode `mode`; the stream's length.
	deflate.DfInit(ws)
	deflate.DfForce(ws, mode)
	port.BufTruncate(z, 0)
	deflate.DfWriteCells(ws, z, src, 0, n)
	deflate.DfFinish(ws, z)
	return port.BufLen(z)
}

func dtVerify(z *port.Buf, src *port.Cells, n int32, dec *port.Cells, st *port.Cells) int32 {
	// -1 when z inflates (header and Adler-32 checked) to exactly src[0, n);
	// -2 for a wrong length; i for the first differing byte; -10 - status
	// when inflate refuses it.
	port.CellsDrop(dec, 0)
	var rc int32 = inflate.IzZlib(port.BufBlob(z), 0, port.BufLen(z), dec, st)
	var i int32 = 0
	if rc != inflate.IzOk() {
		return 0 - (rc + 10)
	}
	if port.CellsLen(dec) != n {
		return -2
	}
	for i < n {
		if port.CellsAt(dec, i) != port.CellsAt(src, i) {
			return i
		}
		i += 1
	}
	return -1
}

func dtSame(a *port.Buf, b *port.Buf) int32 {
	// 1 when the two buffers hold the same bytes.
	var i int32 = 0
	if port.BufLen(a) != port.BufLen(b) {
		return 0
	}
	for i < port.BufLen(a) {
		if port.BufAt(a, i) != port.BufAt(b, i) {
			return 0
		}
		i += 1
	}
	return 1
}

func dtTrip(src *port.Cells, n int32, mode int32) int32 {
	// Compress and verify with fresh state; -1 is a pass.
	var ws *port.Cells = port.NewCells()
	var z *port.Buf = port.NewBuf()
	var dec *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	dtCompress(ws, z, src, n, mode)
	return dtVerify(z, src, n, dec, st)
}

func TestEmptyInputIsTheFixedEmptyBlock(emonT *testing.T) {
	var ws *port.Cells = port.NewCells()
	var z *port.Buf = port.NewBuf()
	deflate.DfInit(ws)
	deflate.DfFinish(ws, z)
	port.AssertEq(emonT, port.BufLen(z), 8, "eight bytes")
	port.AssertEq(emonT, port.BufAt(z, 0), 120, "CMF")
	port.AssertEq(emonT, port.BufAt(z, 1), 1, "FLG")
	port.AssertEq(emonT, port.BufAt(z, 2), 3, "final fixed block, end-of-block")
	port.AssertEq(emonT, port.BufAt(z, 3), 0, "end-of-block, last bits")
	port.AssertEq(emonT, port.BufAt(z, 4), 0, "Adler-32 of nothing: 00")
	port.AssertEq(emonT, port.BufAt(z, 5), 0, "00")
	port.AssertEq(emonT, port.BufAt(z, 6), 0, "00")
	port.AssertEq(emonT, port.BufAt(z, 7), 1, "01")
}

func TestOneByteIsWhatZlibWrites(emonT *testing.T) {
	// zlib's output for `a` with the fixed code: 78 01 4b 04 00 00 62 00 62
	var ws *port.Cells = port.NewCells()
	var z *port.Buf = port.NewBuf()
	deflate.DfInit(ws)
	deflate.DfWriteBlob(ws, z, port.TextBlob("a"), 0, 1)
	deflate.DfFinish(ws, z)
	port.AssertEq(emonT, port.BufLen(z), 9, "nine bytes")
	port.AssertEq(emonT, port.BufAt(z, 2), 75, "4b")
	port.AssertEq(emonT, port.BufAt(z, 3), 4, "04")
	port.AssertEq(emonT, port.BufAt(z, 4), 0, "00")
	port.AssertEq(emonT, port.BufAt(z, 5), 0, "00")
	port.AssertEq(emonT, port.BufAt(z, 6), 98, "62")
	port.AssertEq(emonT, port.BufAt(z, 7), 0, "00")
	port.AssertEq(emonT, port.BufAt(z, 8), 98, "62")
}

