func TestOneMebibyteOfRandomBytesIsStored(emonT *testing.T) {
	// Incompressible blocks are stored: the cost is the five bytes of each
	// block header, and the stream still inflates to the input.
	var src *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var z *port.Buf = port.NewBuf()
	var dec *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	dtFillRandom(src, 1048576, 11)
	var zn int32 = dtCompress(ws, z, src, 1048576, 0)
	port.AssertThat(emonT, zn > 1048576, "stored blocks add their headers")
	port.AssertThat(emonT, zn < (1048576+400), "and only those")
	port.AssertEq(emonT, dtVerify(z, src, 1048576, dec, st), -1, "round trip")
}

