func TestTheOutputDoesNotDependOnHowTheInputIsSplit(emonT *testing.T) {
	var src *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var whole *port.Buf = port.NewBuf()
	var bytewise *port.Buf = port.NewBuf()
	var chunks *port.Buf = port.NewBuf()
	var i int32 = 0
	dtFillText(src, 70000, 13)
	dtCompress(ws, whole, src, 70000, 0)
	deflate.DfInit(ws)
	for i < 70000 {
		deflate.DfWriteCells(ws, bytewise, src, i, i+1)
		i += 1
	}
	deflate.DfFinish(ws, bytewise)
	deflate.DfInit(ws)
	i = 0
	for i < 70000 {
		deflate.DfWriteCells(ws, chunks, src, i, i+1000)
		i += 1000
	}
	deflate.DfFinish(ws, chunks)
	port.AssertEq(emonT, dtSame(whole, bytewise), 1, "byte by byte")
	port.AssertEq(emonT, dtSame(whole, chunks), 1, "in chunks of 1000")
}

